import type { GoalIconName } from "./icons";

/**
 * The wizard's copy and structure live here so the flow can be rewritten
 * without touching a component. Adding a goal is a data edit.
 */

export type GoalId = "define-job" | "score-outcomes" | "test-bet" | "connect-evidence";

export type WizardStepId = "welcome" | "goal" | "readiness" | "launch";

export interface OnboardingGoal {
  id: GoalId;
  title: string;
  blurb: string;
  /** What the user walks away with, shown on the final step. */
  result: string;
  /** Canvas tab revealed when the tour completes. */
  tab: string;
  /** The copilot's first message, shown verbatim before it is sent. */
  prompt: string;
  icon: GoalIconName;
}

export interface OnboardingStep {
  id: WizardStepId;
  label: string;
  title: string;
  lead: string;
}

export const STEPS: OnboardingStep[] = [
  {
    id: "welcome",
    label: "Welcome",
    title: "People don't buy products.",
    lead:
      "They hire them to get a job done. The Living Studio helps you name that job, " +
      "measure how badly it is served, and test the bet before you build.",
  },
  {
    id: "goal",
    label: "Starting point",
    title: "Where do you want to begin?",
    lead: "One starting point. Everything else stays one tab away.",
  },
  {
    id: "readiness",
    label: "Instruments",
    title: "A quick look at your instruments.",
    lead: "The studio runs on your machine. The copilot needs an OpenAI-compatible model to answer.",
  },
  {
    id: "launch",
    label: "First move",
    title: "Make your first move.",
    lead: "The copilot will pick it up from here.",
  },
];

export const GOALS: OnboardingGoal[] = [
  {
    id: "define-job",
    title: "Define the job",
    blurb: "Name the work your customers are trying to get done, step by step.",
    result: "A job to be done, its universal job map, and a first outcome.",
    tab: "jobmap",
    prompt:
      "Help me define a Job-to-be-Done. Ask me who the customer is and what they are " +
      "trying to get done, then capture the job and its first step.",
    icon: "job",
  },
  {
    id: "score-outcomes",
    title: "Score the outcomes",
    blurb: "Rate importance against satisfaction to find the needs nobody serves well.",
    result: "A scored desired outcome and its opportunity score.",
    tab: "landscape",
    prompt:
      "Help me capture and score a desired outcome. Ask me for the outcome statement, " +
      "then its importance and satisfaction.",
    icon: "outcomes",
  },
  {
    id: "test-bet",
    title: "Pressure-test a bet",
    blurb: "Simulate the impact of an idea before you spend a sprint on it.",
    result: "A before-and-after impact simulation for one bet.",
    tab: "impact",
    prompt:
      "Walk me through simulating a bet. Ask me which outcome I want to pressure-test " +
      "and what the bet is.",
    icon: "bet",
  },
  {
    id: "connect-evidence",
    title: "Connect evidence",
    blurb: "Bring customer calls, support tickets, and telemetry into the map.",
    result: "Your evidence sources, wired back to the outcomes they support.",
    tab: "evidence",
    prompt:
      "Show me which evidence sources are connected and how to bring customer signal " +
      "into the studio.",
    icon: "evidence",
  },
];

export const GOAL_STEP_INDEX = STEPS.findIndex((step) => step.id === "goal");

export function goalById(id: GoalId | null): OnboardingGoal | null {
  if (!id) {
    return null;
  }
  return GOALS.find((goal) => goal.id === id) ?? null;
}

