import { Fragment, type ReactNode } from "react";

/**
 * A deliberately small inline-markdown renderer.
 *
 * The agent still writes prose, and prose with literal `**` and `###` in it is
 * what made the old transcript feel like a log file. This handles the four
 * constructs that actually show up — bold, italic, inline code, links — plus
 * paragraphs, bullets and modest headings. Structure belongs to cards; this is
 * for the sentence around them.
 *
 * Nothing here can inject markup: every branch returns React elements or plain
 * strings, so React escapes it all.
 */

const LINK_PATTERN = /^\[([^\]]+)\]\(([^)\s]+)\)$/;

const INLINE_PATTERN = /(\*\*[^*]+\*\*|\*[^*\n]+\*|`[^`\n]+`|\[[^\]]+\]\([^)\s]+\))/g;

function renderInline(text: string, keyPrefix: string): ReactNode[] {
  const nodes: ReactNode[] = [];
  let lastIndex = 0;
  let match: RegExpExecArray | null;
  const pattern = new RegExp(INLINE_PATTERN);
  let index = 0;

  while ((match = pattern.exec(text)) !== null) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index));
    }
    const token = match[0];
    const key = `${keyPrefix}-${index}`;
    index += 1;

    if (token.startsWith("**")) {
      nodes.push(<strong key={key}>{token.slice(2, -2)}</strong>);
    } else if (token.startsWith("`")) {
      nodes.push(
        <code className="ui-code" key={key}>
          {token.slice(1, -1)}
        </code>,
      );
    } else if (token.startsWith("[")) {
      const link = LINK_PATTERN.exec(token);
      const href = link?.[2] ?? "";
      const safe = /^https?:\/\//i.test(href);
      nodes.push(
        safe ? (
          <a href={href} key={key} rel="noreferrer noopener" target="_blank">
            {link?.[1] ?? href}
          </a>
        ) : (
          <Fragment key={key}>{link?.[1] ?? token}</Fragment>
        ),
      );
    } else {
      nodes.push(<em key={key}>{token.slice(1, -1)}</em>);
    }

    lastIndex = match.index + token.length;
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex));
  }

  return nodes;
}

type Block =
  | { kind: "paragraph"; lines: string[] }
  | { kind: "list"; ordered: boolean; items: string[] }
  | { kind: "heading"; level: number; text: string };

function toBlocks(text: string): Block[] {
  const blocks: Block[] = [];
  const lines = text.replace(/\r\n/g, "\n").split("\n");

  for (const raw of lines) {
    const line = raw.trimEnd();

    if (line.trim() === "") {
      blocks.push({ kind: "paragraph", lines: [] });
      continue;
    }

    const heading = /^(#{1,6})\s+(.*)$/.exec(line);
    if (heading) {
      blocks.push({
        kind: "heading",
        level: Math.min(4, Math.max(3, heading[1].length + 2)),
        text: heading[2],
      });
      continue;
    }

    const bullet = /^\s*[-*]\s+(.*)$/.exec(line);
    const numbered = /^\s*\d+[.)]\s+(.*)$/.exec(line);
    if (bullet || numbered) {
      const ordered = Boolean(numbered);
      const value = (bullet?.[1] ?? numbered?.[1] ?? "").trim();
      const previous = blocks[blocks.length - 1];
      if (previous?.kind === "list" && previous.ordered === ordered) {
        previous.items.push(value);
      } else {
        blocks.push({ kind: "list", ordered, items: [value] });
      }
      continue;
    }

    const previous = blocks[blocks.length - 1];
    if (previous?.kind === "paragraph" && previous.lines.length > 0) {
      previous.lines.push(line);
    } else {
      blocks.push({ kind: "paragraph", lines: [line] });
    }
  }

  return blocks;
}

export function RichText({ text }: { text: string }) {
  const blocks = toBlocks(text);
  const rendered: ReactNode[] = [];

  blocks.forEach((block, index) => {
    const key = `block-${index}`;

    if (block.kind === "heading") {
      const Tag = block.level <= 3 ? "h4" : "h5";
      rendered.push(
        <Tag className="ui-richtext__heading" key={key}>
          {renderInline(block.text, key)}
        </Tag>,
      );
      return;
    }

    if (block.kind === "list") {
      const Tag = block.ordered ? "ol" : "ul";
      rendered.push(
        <Tag className="ui-richtext__list" key={key}>
          {block.items.map((item, itemIndex) => (
            <li key={`${key}-${itemIndex}`}>{renderInline(item, `${key}-${itemIndex}`)}</li>
          ))}
        </Tag>,
      );
      return;
    }

    if (block.lines.length === 0) {
      return;
    }

    rendered.push(
      <p className="ui-richtext__paragraph" key={key}>
        {block.lines.map((line, lineIndex) => (
          <Fragment key={`${key}-${lineIndex}`}>
            {lineIndex > 0 && <br />}
            {renderInline(line, `${key}-${lineIndex}`)}
          </Fragment>
        ))}
      </p>,
    );
  });

  return <div className="ui-richtext">{rendered}</div>;
}

